# -*- coding: utf-8 -*-
"""HarvestGuard Rwanda — Streamlit application.

This dashboard uses the already-generated Model V3 candidate vulnerability outputs
and verifies that the downloaded candidate bundle is present.
It does not retrain the model.
"""

from pathlib import Path
import base64
import gzip
import json

import pandas as pd
import streamlit as st

from harvestguard_views import render_model_evidence
from harvestguard_decisions import build_brief, load_knowledge_base
from harvestguard_map import build_map
from harvestguard_ui import apply_design, hero, card, ranking_cards
from harvestguard_ai_view import render_ai_advisor
from harvestguard_data import MODEL_FOLDER, dashboard_signature, load_dashboard_data, rank_districts

st.set_page_config(
    page_title="HarvestGuard Rwanda",
    page_icon="🌾",
    layout="wide",
    initial_sidebar_state="expanded",
)

APP_DIR = Path(__file__).resolve().parent
MODEL_DIR = APP_DIR / MODEL_FOLDER

# Rwanda ADM2 geometry embedded in the approved Saturday map implementation so
# the app has no extra boundary-file dependency.
GEO_B64 = ''


@st.cache_data(show_spinner=False)
def load_data(signature):
    risk, metadata, readiness = load_dashboard_data(MODEL_DIR)
    geo = json.loads(gzip.decompress(base64.b64decode(GEO_B64)).decode("utf-8"))
    return risk, metadata, readiness, geo


try:
    risk, metadata, readiness, geo = load_data(dashboard_signature(MODEL_DIR))
except (OSError, ValueError, TypeError) as error:
    st.error(f"Could not load the Model V3 candidate. Keep the complete `model_v3_candidate` folder next to the dashboard. {error}")
    st.stop()

apply_design()

with st.sidebar:
    st.markdown('<div class="hg-brand"><strong>🌾 HarvestGuard</strong><small>RWANDA · PROTECT EVERY HARVEST</small></div>', unsafe_allow_html=True)
    page = st.radio("Explore", ["Map", "Insights"], key="page", horizontal=True)
    st.divider()
    seasons = sorted(risk["season"].dropna().astype(str).unique().tolist())
    season = st.selectbox("Season", seasons, key="season")
    crop_options = sorted(risk.loc[risk["season"].astype(str) == season, "crop_name"].dropna().unique().tolist())
    if st.session_state.get("crop") not in crop_options:
        st.session_state["crop"] = "Maize" if "Maize" in crop_options else crop_options[0]
    crop = st.selectbox("Crop", crop_options, key="crop")

view = risk[(risk["season"].astype(str) == season) & (risk["crop_name"] == crop)].copy()
view = rank_districts(view)
if view.empty:
    st.info("No saved prediction for this selection. Choose another crop or season.")
    st.stop()
quantity = "predicted_loss_kg" in view
ranking_column = "predicted_loss_kg" if quantity else "predicted_loss_pct"
scope_note = (
    "Quantities are survey-expanded estimates for the covered profiles and crops."
    if metadata["loss_quantity_scope"] == "survey_expanded" else
    "Quantities cover sampled profiles only; district population totals require verified survey expansion weights."
    if quantity else
    "Production quantities are missing from this saved export. This is a loss-rate view; kg-based intervention priorities are unavailable. Rerun the revised Colab notebook with profile production."
)
top = view.iloc[0]
districts = view["district"].tolist()
selection = (season, crop)
if st.session_state.get("_crop_season") != selection or st.session_state.get("brief_district") not in districts:
    st.session_state["brief_district"] = districts[0]
    st.session_state["_crop_season"] = selection

with st.sidebar:
    selected_district = st.selectbox("District", districts, key="brief_district")
    st.caption("HarvestGuard loss model")
    st.caption("2025 historical predictions")
    st.caption("Storage · Processing · Packaging")
    st.divider()
    st.caption("Choose a district, then open Insights. Explanations appear automatically.")

selected = view.loc[view["district"] == selected_district].iloc[0]
def show_insights():
    st.session_state["page"] = "Insights"


if page == "Map":
    hero("Where should we look first?" if quantity else "Historical loss rates", "Explore estimated kg lost, district by district." if quantity else "Quantity priorities require profile production data.", f"{crop} · Season {season} · 2025")
    one, two, three = st.columns(3)
    one.metric("Highest estimated loss" if quantity else "Highest predicted rate", f"{float(top['predicted_loss_kg']):,.2f} kg" if quantity else f"{float(top['predicted_loss_pct']):.2f}%")
    two.metric("First in this selection", str(top["district"]))
    three.metric("Districts with predictions", f"{len(view)} / 30")
    map_col, priority_col = st.columns([2.4, 1], gap="large")
    with map_col:
        st.markdown("### The district picture")
        st.markdown('<div class="hg-legend"><span><i class="hg-dot" style="background:#e4ac6d"></i>Top five</span><span><i class="hg-dot" style="background:#d2ddba"></i>Other predictions</span><span><i class="hg-dot" style="background:#e4e2db"></i>No prediction</span><span>Dark outline = selected district</span></div>', unsafe_allow_html=True)
        st.plotly_chart(build_map(view, geo, selected_district), width="stretch", config={"displayModeBar": False, "scrollZoom": False, "doubleClick": False, "responsive": True})
    with priority_col:
        st.markdown("### Highest estimated kg lost" if quantity else "### Five highest rates")
        ranking_cards(view)
        st.markdown("<br>", unsafe_allow_html=True)
        amount = f"{float(selected['predicted_loss_kg']):,.2f} kg lost · " if quantity else ""
        card("Your selection", selected_district, f"{crop} · {amount}{float(selected['predicted_loss_pct']):.2f}% expected loss · rank #{int(selected['display_rank'])}", tone="green")
        st.button("See insights →", type="primary", on_click=show_insights, width="stretch")
    if view[ranking_column].duplicated(keep=False).any():
        st.caption("Some districts share the same score; their order does not imply a meaningful difference.")
    with st.expander("All districts & download"):
        columns = ["display_rank", "district", "predicted_loss_pct", "n_profiles", "support_level"]
        if quantity:
            columns += ["production_kg", "predicted_loss_kg", "predicted_loss_tonnes", "observed_loss_kg", "loss_quantity_scope"]
        table = view[columns].rename(columns={"display_rank": "Rank", "district": "District", "predicted_loss_pct": "Expected loss %", "n_profiles": "Profiles", "support_level": "Sample support"})
        st.dataframe(table, width="stretch", hide_index=True, column_config={"Expected loss %": st.column_config.NumberColumn(format="%.2f")})
        st.caption("Profile count describes sample support, not confidence. " + scope_note)
        st.download_button("Download ranking", table.to_csv(index=False).encode("utf-8"), file_name=f"harvestguard_{season}_{crop.replace(' ', '_')}_ranking_2025.csv", mime="text/csv")
else:
    hero(f"{selected_district}: from insight to action", "Understand the prediction. Prioritize intervention using our findings.", f"{crop} · Season {season} · 2025")
    one, two, three = st.columns(3)
    one.metric("Estimated loss" if quantity else "Expected loss", f"{float(selected['predicted_loss_kg']):,.2f} kg" if quantity else f"{float(selected['predicted_loss_pct']):.2f}%")
    two.metric("District rank", f"{int(selected['display_rank'])} / {len(view)}")
    three.metric("Production-weighted loss rate" if quantity else "Illustration per tonne", f"{float(selected['predicted_loss_pct']):.2f}%" if quantity else f"{float(selected['predicted_loss_pct']) * 10:.2f} kg")
    st.caption("Estimated loss across storage, processing and packaging. " + ("Districts are ranked by kg lost." if quantity else "Per-tonne value is an illustration."))
    try:
        kb = load_knowledge_base(APP_DIR / "knowledge_base" / "interventions.json")
        diagnostic_path = MODEL_DIR / "external_validation_by_season_2025.csv"
        positive_cases = None
        if diagnostic_path.exists():
            diagnostics = pd.read_csv(diagnostic_path)
            if {"season", "positive_cases"}.issubset(diagnostics.columns):
                match = diagnostics.loc[diagnostics["season"].astype(str) == season]
                if not match.empty and pd.notna(match.iloc[0]["positive_cases"]):
                    positive_cases = int(match.iloc[0]["positive_cases"])
        brief = build_brief(selected.to_dict(), metadata, kb, district_count=len(view), season_positive_cases=positive_cases)
    except (OSError, ValueError, KeyError, TypeError):
        st.error("The supporting evidence could not be loaded. The saved prediction is shown above.")
        st.stop()
    render_ai_advisor(brief, view, APP_DIR, model_dir=MODEL_DIR)

with st.expander("Metadata and Methodology"):
    render_model_evidence(metadata, readiness, MODEL_DIR)

st.markdown('<div class="hg-footer">HarvestGuard Rwanda · NISR seasonal agricultural data · 2025 analysis</div>', unsafe_allow_html=True)
